def hex_word_sum(input_string):
    def is_valid_hex(word):
        word = word.replace('O', '0').replace('S', '5')
        try:
            int(word, 16)
            return True
        except ValueError:
            return False

    words = input_string.split()
    total_sum = 0
    for word in words:
        if is_valid_hex(word):
            total_sum += int(word.replace('O', '0').replace('S', '5'), 16)
    return total_sum
